/*
 * Mini-Netflix database: about 3 600 more Vietnamese sample rows.
 * Run once, right after 06_seed_sample_data.sql (before or after 07 and 08).
 * It continues the explicit ids of 06, so it stops with a clear message if
 * the database is not in the state 06 leaves it in.
 *
 * Viewing times are computed when the script runs, inside each user's latest
 * non-cancelled subscription, so the rows stay valid on any run date.
 * Every account added here has the test password 'demo123'.
 */

SET client_encoding = 'UTF8';

BEGIN;

DO $$
BEGIN
    IF (SELECT MAX(title_id) FROM titles) <> 30
    OR (SELECT MAX(content_id) FROM contents) <> 125
    OR (SELECT MAX(subscription_id) FROM subscriptions) <> 48
    OR (SELECT MAX(person_id) FROM people) <> 32
    OR EXISTS (SELECT 1 FROM users WHERE user_id = 'U000031')
    THEN
        RAISE EXCEPTION 'Expected the database exactly as 06_seed_sample_data.sql leaves it; this script may already have run';
    END IF;
END;
$$;

/* ---------- 70 accounts: U000031 to U000100 ---------- */

