/*
 * ---------- 2600 viewing sessions ----------
 * slot is the position of the session inside the window from the user's
 * latest non-cancelled subscription start to today minus idle_days
 * (0 = start, 1 = end). idle_days > 0 marks accounts that stopped watching.
 * Times are whole minutes plus 17 seconds, so they never collide with the
 * sessions of 06, which all fall on whole minutes.
 */
INSERT INTO watch_history (user_id, profile_num, content_id, started_at, ended_at, position_seconds)
SELECT v.user_id,
       v.profile_num,
       v.content_id,
       st.started_at,
       CASE WHEN v.is_ended
            THEN st.started_at + ps.position_seconds * INTERVAL '1 second'
       END,
       ps.position_seconds
