               ('U000100', 3, 131, 0.307609, 1.0000, TRUE, 25),
               ('U000100', 3, 139, 0.333894, 1.0000, TRUE, 25),
               ('U000100', 3, 103, 0.383888, 1.0000, TRUE, 25),
               ('U000100', 3, 11, 0.433978, 0.1148, TRUE, 25),
               ('U000100', 3, 204, 0.476693, 1.0000, TRUE, 25),
               ('U000100', 3, 140, 0.527427, 0.9318, TRUE, 25),
               ('U000100', 3, 131, 0.565780, 0.9722, TRUE, 25),
               ('U000100', 3, 205, 0.613878, 0.5276, TRUE, 25),
               ('U000100', 3, 11, 0.656951, 1.0000, TRUE, 25),
               ('U000100', 3, 8, 0.706369, 0.2883, TRUE, 25),
               ('U000100', 3, 8, 0.763044, 0.9722, TRUE, 25),
               ('U000100', 3, 8, 0.808591, 1.0000, TRUE, 25),
               ('U000100', 3, 104, 0.846409, 0.9768, TRUE, 25),
               ('U000100', 3, 206, 0.887254, 0.6757, TRUE, 25),
               ('U000100', 3, 9, 0.914243, 1.0000, TRUE, 25),
               ('U000100', 3, 8, 0.968315, 0.2175, TRUE, 25)
       ) AS v (user_id, profile_num, content_id, slot, position_ratio, is_ended, idle_days)
       CROSS JOIN LATERAL (
           SELECT s.start_date,
                  LEAST(s.end_date, CURRENT_DATE - v.idle_days) AS window_end
             FROM subscriptions AS s
            WHERE s.user_id = v.user_id
              AND s.subscription_status <> 'CANCELLED'
              AND s.start_date < CURRENT_DATE
            ORDER BY s.start_date DESC
            LIMIT 1
       ) AS sw
       CROSS JOIN LATERAL (
           SELECT sw.start_date
                  + ROUND((sw.window_end - sw.start_date) * 1440 * v.slot) * INTERVAL '1 minute'
                  + INTERVAL '17 seconds' AS started_at
       ) AS st
       INNER JOIN contents AS c
       ON c.content_id = v.content_id

       CROSS JOIN LATERAL (
           SELECT LEAST(c.duration_seconds, ROUND(c.duration_seconds * v.position_ratio))::INTEGER AS position_seconds
       ) AS ps;

